//! Panic-injection fuzzing, oracle L5: a framework bug (fixed in #309).
//! A handler panicked with a payload whose destructor panics
//! (`PAYLOAD_DROP`). The run loop dropped the payload in place, so the second
//! panic unwound the lifecycle: `stopped()` never ran and the reason became
//! "actor lifecycle unwound". Every caught payload now goes through
//! `dispose_panic`. Minimized from 48 to 45 bytes by `cargo fuzz tmin`.
//!
//! Generated by `cargo run --example repro -- <input> --emit exploding_panic_payload_keeps_stopped`.
//!
//! Failure: none (passing input)
//! Strategy random, seed 5202017910563.
//!
//! ```text
//! Scenario {
//!     seed: 5202017910563,
//!     sched: Random,
//!     ops: [
//!         Op(
//!             Spawn {
//!                 how: Unmanaged,
//!                 hooks: Hooks {
//!                     flags: 30,
//!                     started_sleep: 30,
//!                     stopped_sleep: 22,
//!                 },
//!             },
//!         ),
//!         Fault(
//!             Arm {
//!                 sites: 7710,
//!                 mask: 7710,
//!             },
//!         ),
//!         Op(
//!             Request {
//!                 to: 30,
//!                 cmd: Panic,
//!                 timeout: Some(
//!                     0,
//!                 ),
//!                 detached: false,
//!             },
//!         ),
//!     ],
//! }
//! ```
#![cfg(spawned_sim)]

const INPUT: &[u8] = include_bytes!("../regressions/exploding_panic_payload_keeps_stopped.input");
const TAPE: &str = include_str!("../regressions/exploding_panic_payload_keeps_stopped.tape");

/// The input under its own schedule and under its recorded tape.
#[test]
fn exploding_panic_payload_keeps_stopped_tape() {
    spawned_fuzz::assert_passes_faults(INPUT, Some(TAPE));
}

/// The same operations under other simulator schedules.
#[spawned_macros::sim_test(seeds = 32)]
async fn exploding_panic_payload_keeps_stopped_seeds(seed: u64) {
    spawned_fuzz::init();
    spawned_fuzz::run_body(spawned_fuzz::decode_faults(INPUT).unwrap(), seed).await;
}
